/* HEXA BATTLEGROUNDS upgrade2 — PART 27 OF 32. For databases that already ran supabase/upgrade (match phases); Run in order. Safe to re-run. */ create or replace function _autopilot(p_arena uuid) returns boolean language plpgsql as $$ declare a arenas; v_ev uuid; v_fam text; v_n int; v_pos int; v_fm int; st text[]; v_open int; v_res boolean := false; v_stat jsonb; begin if coalesce(current_setting('hb.in_auto', true), '') = '1' then return false; end if; select * into a from arenas where id = p_arena; if a.id is null or not a.autopilot or a.paused or a.phase = 'ended' then return false; end if; v_ev := a.event_id; perform set_config('hb.in_auto', '1', true); begin v_fam := case when a.phase in ('lobby', 'boarding') then 'boarding' when a.phase in ('shuttle', 'roles') then 'ride' when a.phase = 'play' then 'play' else 'fin' end; if split_part(coalesce(a.auto_step, ''), ':', 1) <> v_fam then perform _auto_resync(a.id); select * into a from arenas where id = p_arena; v_res := true; end if; if a.phase = 'lobby' then if exists (select 1 from teams where arena_id = a.id and ready) then perform _host_exec(v_ev, a.id, 'open_boarding', '{}'::jsonb, 'autopilot'); update arenas set auto_step = 'boarding', auto_next_at = now() + _secs(coalesce(_cfg(v_ev, 'boarding_seconds'), 18)) where id = a.id; insert into audit_log(event_id, arena_id, actor, action) values (v_ev, a.id, 'autopilot', 'open_boarding'); v_res := true; end if; elsif a.phase = 'boarding' then if a.auto_next_at is not null and now() >= a.auto_next_at then if exists (select 1 from teams where arena_id = a.id and ready) then perform _host_exec(v_ev, a.id, 'drive', '{}'::jsonb, 'autopilot'); update arenas set auto_step = 'ride', auto_next_at = null where id = a.id; insert into audit_log(event_id, arena_id, actor, action) values (v_ev, a.id, 'autopilot', 'drive'); else update arenas set auto_next_at = now() + interval '10 seconds' where id = a.id; end if; v_res := true; end if; elsif a.phase = 'play' then if a.match_phase > a.auto_story then st := _auto_story(a.match_phase); update arenas set auto_story = a.match_phase where id = a.id; perform _host_exec(v_ev, a.id, 'story', jsonb_build_object('title', st[1], 'body', st[2]), 'autopilot'); if a.match_phase in (2, 3) then perform _host_exec(v_ev, a.id, 'bargain', jsonb_build_object('title', 'Squad 00 offers a deal', 'body', case a.match_phase when 2 then 'Take our coins now. All it costs is a little of your squad''s trust.' else 'A bigger offer. Accept, and the threat on this map rises.' end, 'coins', case a.match_phase when 2 then 60 else 90 end, 'threat', 1, 'trust', case a.match_phase when 2 then -5 else -10 end, 'minutes', 2), 'autopilot'); end if; v_res := true; end if; v_fm := _auto_finale_minute(v_ev); if a.play_started_at is not null and now() >= a.play_started_at + make_interval(mins => v_fm) then perform _host_exec(v_ev, a.id, 'begin_finale', '{}'::jsonb, 'autopilot'); update arenas set auto_step = 'fin:0', auto_next_at = now() + interval '12 seconds', match_phase = 5, phase_started_at = now(), phase_next_at = null, overlay = overlay || jsonb_build_object('match', jsonb_build_object('phase', 5, 'started_at', now(), 'next_at', null, 'zone_target', 5)) where id = a.id; perform _feed(a.id, 'phase.started', jsonb_build_object('phase', 5)); insert into audit_log(event_id, arena_id, actor, action) values (v_ev, a.id, 'autopilot', 'begin_finale'); v_res := true; end if; elsif a.phase in ('finale', 'results') then v_n := greatest(1, coalesce(_cfg(v_ev, 'finale_battles'), 2)); if a.sync_round_id is not null then select count(*) into v_open from mission_instances where sync_round_id = a.sync_round_id and status = 'active'; if v_open = 0 then perform _host_exec(v_ev, a.id, 'close_sync', '{}'::jsonb, 'autopilot'); v_res := true; end if; elsif a.auto_next_at is null then update arenas set auto_next_at = now() + interval '10 seconds' where id = a.id; v_res := true; elsif now() >= a.auto_next_at then v_pos := _auto_fin_pos(a.id); if v_pos < 2 + v_n then perform _host_exec(v_ev, a.id, 'finale_stage', jsonb_build_object('stage', case when v_pos = 0 then 'A' when v_pos = 1 then 'B' else 'C' end), 'autopilot'); perform _host_exec(v_ev, a.id, 'launch_sync', jsonb_build_object('kind', case when v_pos = 0 then 'finale_entry' when v_pos = 1 then 'finale_exchange' else 'finale_battle' end), 'autopilot'); update arenas set auto_next_at = null where id = a.id; elsif v_pos = 2 + v_n then perform _host_exec(v_ev, a.id, 'reveal_squad00', '{}'::jsonb, 'autopilot'); update arenas set auto_next_at = now() + interval '30 seconds' where id = a.id; elsif v_pos = 3 + v_n then perform _host_exec(v_ev, a.id, 'finale_stage', jsonb_build_object('stage', 'E'), 'autopilot'); perform _host_exec(v_ev, a.id, 'launch_sync', jsonb_build_object('kind', 'final_code'), 'autopilot'); update arenas set auto_next_at = null where id = a.id; elsif v_pos = 4 + v_n then perform _host_exec(v_ev, a.id, 'lock_results', '{}'::jsonb, 'autopilot'); update arenas set auto_next_at = now() + interval '15 seconds' where id = a.id; elsif v_pos = 5 + v_n then perform _host_exec(v_ev, a.id, 'reveal_winner', '{}'::jsonb, 'autopilot'); update arenas set auto_next_at = now() + interval '20 seconds' where id = a.id; elsif v_pos = 6 + v_n then if not exists (select 1 from arenas x where x.event_id = v_ev and not x.winner_revealed and exists (select 1 from teams where arena_id = x.id and ready)) then update events set grand_revealed = true where id = v_ev; perform _ping_arena(x.id, 'grand') from arenas x where x.event_id = v_ev; end if; end if; if v_pos < 6 + v_n or (select grand_revealed from events where id = v_ev) then insert into audit_log(event_id, arena_id, actor, action, args) values (v_ev, a.id, 'autopilot', 'finale_step', jsonb_build_object('step', _auto_step_name(v_pos, v_n))); v_res := true; end if; end if; update arenas set auto_step = 'fin:' || _auto_fin_pos(a.id) where id = a.id; end if; v_stat := _auto_status(a.id) - 'step'; update arenas set overlay = overlay || jsonb_build_object('auto', v_stat) where id = a.id and overlay -> 'auto' is distinct from v_stat; if found then v_res := true; end if; exception when others then perform set_config('hb.in_auto', '', true); if not exists (select 1 from audit_log where arena_id = a.id and actor = 'autopilot' and not ok and at > now() - interval '30 seconds') then insert into audit_log(event_id, arena_id, actor, action, ok, error) values (v_ev, a.id, 'autopilot', 'step', false, sqlerrm); end if; return false; end; perform set_config('hb.in_auto', '', true); if v_res then perform _ping_arena(a.id, 'auto'); end if; return v_res; end $$;
